-- 0061 · The lease contracts, as sales orders
--
-- Generated by scripts/generate-lease-contracts.py. Do not hand-edit.
--
-- The Lease Revenue Monitoring sheet is the record of what is out with
-- customers, and none of it was in the system. That is why the fleet
-- reads zero leased while a hundred and seven units are standing in
-- somebody else's yard, and why a count cannot tell a missing unit from
-- a deployed one.
--
-- A contract is a sales order of type LEASE. Sales orders already take an
-- uploaded document, so the signed contract hangs on the order.


/*
 * The system already models a lease contract - 0018 built it, with the
 * customer, the term, the daily rate, the unit list and a place for the
 * signed document. Nothing was ever loaded into it. So this fills the
 * table that exists rather than inventing a second one beside it.
 *
 * What that table has no room for is the batch: the sheet keys everything
 * on a client-batch code, and the SOA tab bills against it. That goes in a
 * side table, along with the model split, so the contract can be found by
 * the code Finance actually uses.
 */
CREATE TABLE IF NOT EXISTS erp_lease_contract_batches (
  lease_contract_id INTEGER PRIMARY KEY REFERENCES erp_lease_contracts(id),
  cb_code TEXT NOT NULL,            -- client + batch, the key the SOA bills on
  client_code TEXT,
  batch_code TEXT,
  addendum TEXT,
  transaction_type TEXT,            -- LSE | L2O
  transaction_code TEXT,
  units_r280 INTEGER NOT NULL DEFAULT 0,
  units_r280s INTEGER NOT NULL DEFAULT 0,
  units_d400 INTEGER NOT NULL DEFAULT 0,
  charging_kits INTEGER NOT NULL DEFAULT 0,
  batteries INTEGER NOT NULL DEFAULT 0,
  source_key TEXT UNIQUE
);
CREATE INDEX IF NOT EXISTS idx_lease_batch_cb ON erp_lease_contract_batches(cb_code);

/*
 * Which unit is out on which contract, and when it came back.
 *
 * erp_lease_contract_units says which units a contract covers. This says
 * where a unit physically is, which is a different question and the one a
 * count asks: a serial nobody can find in the warehouse is not missing if
 * it is standing in a customer's yard.
 *
 * Returning closes the row rather than deleting it, because where a unit
 * has been is part of its history.
 */
CREATE TABLE IF NOT EXISTS erp_asset_deployments (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  serial_no TEXT NOT NULL,
  asset_id INTEGER REFERENCES erp_assets(id),
  lease_contract_id INTEGER REFERENCES erp_lease_contracts(id),
  sales_order_id INTEGER REFERENCES erp_sales_orders(id),
  cb_code TEXT,
  customer_id INTEGER REFERENCES erp_partners(id),
  customer_name TEXT,
  deployed_at TEXT NOT NULL DEFAULT (datetime('now')),
  deployed_by TEXT,
  count_sheet_id INTEGER,           -- when a count is what discovered it
  returned_at TEXT,
  returned_by TEXT,
  return_reason TEXT,
  note TEXT
);
CREATE INDEX IF NOT EXISTS idx_deploy_serial ON erp_asset_deployments(serial_no, returned_at);
CREATE INDEX IF NOT EXISTS idx_deploy_contract ON erp_asset_deployments(lease_contract_id);
CREATE UNIQUE INDEX IF NOT EXISTS ux_deploy_open ON erp_asset_deployments(serial_no)
  WHERE returned_at IS NULL;



